const SIZE_ORDER=["XXS","XS","S","M","L","XL","XXL","XXXL"];
const sizeRank=v=>{const n=String(v||"").trim().toUpperCase();const i=SIZE_ORDER.indexOf(n);return i<0?SIZE_ORDER.length:i};
const NCM_BRANCH_CACHE={items:null};
async function getNcmBranches(){
  if(NCM_BRANCH_CACHE.items?.length)return NCM_BRANCH_CACHE.items;
  const{data,error}=await supabase.functions.invoke("ncm-branches");
  if(error)throw error;
  const branches=Array.isArray(data)?data:(data?.branches||[]);
  NCM_BRANCH_CACHE.items=branches;
  return branches;
}
const ncmNorm=v=>String(v||"").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g," ").trim();
function matchNcmBranch(branches,city,district){
  const c=ncmNorm(city),d=ncmNorm(district);
  if(!c&&!d)return "";
  let best=null,bestScore=0;
  for(const b of branches){
    const name=ncmNorm(b.name),bd=ncmNorm(b.district_name),areas=ncmNorm(b.areas_covered);
    let score=0;
    if(c&&name===c)score=100;
    else if(d&&name===d)score=95;
    else if(c&&bd===c)score=90;
    else if(d&&bd===d)score=85;
    else if(c&&areas.includes(c))score=80;
    else if(d&&areas.includes(d))score=70;
    if(score>bestScore){bestScore=score;best=b.name}
  }
  return best||"";
}
